// GENERATED by scripts/sync-rule-engine.mjs from feasibility_initial_20_11/server.ts.
// Do not edit by hand: re-run the script when a new AI Studio export arrives.
//
// The original Express server answered chat messages with this function on POST /api/chat.
// The Flask version runs it in the browser instead (see ChatPane.tsx), so the rules stay
// identical to the original and the shared database is not uploaded with every message.
import { parseNaturalLanguageSpecs } from './chatParser';
import { getCountryPreExistingSpecs } from '../data/attachedSpecsData';

export function processRuleBasedQuery(messages: any[], dataState: any, activeStrategy: string) {
  const lastMsg = messages[messages.length - 1]?.text || "";
  const query = lastMsg.toLowerCase();

  const originalPitches = dataState?.pitches || [];
  const pitchesMap = new Map<string, any>(originalPitches.map((p: any) => [p.id, { ...p }]));
  const insertedDb = Array.isArray(dataState?.insertedDatabase) && dataState.insertedDatabase.length > 0
    ? dataState.insertedDatabase
    : undefined;

  let text = "";
  let updateStrategy: string | undefined = undefined;
  let hasModifications = false;

  const isRuleQuestion =
    /\b(rule|rules|regula|reguli|explain|how does|how do|what is the|care este)\b/i.test(query);

  const isAddIntent =
    !isRuleQuestion &&
    (
      /\b(add|insert|adauga|adaugă)\b.*\b(line|row|linie|scenariu|scenario|audience|audienta|audiență)\b/i.test(query) ||
      /^\s*(add|insert|adauga|adaugă)\b/i.test(query)
    );

  // 1. LOI, IR & QUOTAS RULES EXPLANATION (guarded so "add ... LOI ... No quotas" never hits this branch)
  if (
    !isAddIntent &&
    (
      query.includes("rule loi") ||
      query.includes("loi rule") ||
      query.includes("regula loi") ||
      (query.includes("loi") && (isRuleQuestion || query.includes("higher") || query.includes("lower") || query.includes("5 min") || query.includes("10 min") || query.includes("assumption") || query.includes("markup")))
    )
  ) {
    text = `### 📏 LOI (Duration) Calculation Rule

* **LOI lower by up to 10 minutes vs database**:
  * We continue to quote using database records with the same prices and capacities (no penalty or markup).
  * *Example*: If the database has 15 min and we request 10 min (5 min difference <= 10 min), it quotes at standard database rates.

* **LOI higher by up to 5 minutes vs database**:
  * We reuse the database record to ensure feasibility coverage.
  * **A safety mark-up of +10% is automatically applied to Weighted CPI**.
  * On hover over the Weighted CPI cell, a dedicated note is displayed: *"LOI Assumption: Requested LOI is higher by up to 5m vs database. Applied +10% safety mark-up on Weighted CPI."*

* **Larger differences**:
  * A requested LOI higher by more than 5 minutes or lower by more than 10 minutes is considered unfeasible (0 output).`;
  }
  else if (
    !isAddIntent &&
    (
      query.includes("rule incidence") ||
      query.includes("ir rule") ||
      query.includes("regula incidenta") ||
      (query.includes("incident") && (isRuleQuestion || query.includes("minus") || query.includes("lower") || query.includes("higher") || query.includes("decrease") || query.includes("10%")))
    )
  ) {
    text = `### 🎯 Incidence (IR%) Calculation Rule

* **Incidence lower by up to -10% vs database**:
  * Generated feasibility (available panel completes capacity) **is directly reduced by this percentage** to reflect recruitment difficulty.
  * *Example*: If the database has 30% IR and we request 23% IR (-7% difference), panel and vendor capacities are automatically reduced by 7%.

* **Incidence higher vs database**:
  * The **closest feasibility from the database** is used for that universe, **without applying reduction factors** (factor = 1.0), as higher incidence is practically easier to fulfill.

* **Differences over 10% lower**:
  * If the requested incidence is lower by more than 10% vs the database, it is marked as unfeasible (0 output).`;
  }
  else if (
    !isAddIntent &&
    (query.includes("quota") || query.includes("no quotas") || query.includes("cote") || query.includes("fara cote"))
  ) {
    text = `### 📋 Quotas Rule

* **"No quotas" option**:
  * Selecting **"no quotas"** (or *None*) matches and accepts **any feasibility record in the database for that universe (with or without specific quotas such as AGR, Age & Gender, etc.)**.
  * Even if the database only contains quota-specific entries, a "No quotas" request will utilize those capacities and standard prices.`;
  }
  // 2. CHEAPEST VENDOR / SOURCE / RATES (must come BEFORE general "cheapest" optimization branch)
  else if (query.includes("cheapest source") || query.includes("cheapest vendor") || query.includes("lowest cpi") || query.includes("best rate")) {
    let bestVendor = "";
    let minCpi = Infinity;
    const activeVendors = Array.isArray(dataState?.vendors) ? dataState.vendors : [];
    originalPitches.forEach((p: any) => {
      for (const k of Object.keys(p)) {
        const m = k.match(/^vendor(\d+)Cpi$/i);
        if (m) {
          const idx = parseInt(m[1], 10) - 1;
          const vMeta = activeVendors[idx];
          const isBanned = vMeta && (String(vMeta.tier || '').toLowerCase().includes('do not use') || String(vMeta.color || '').toLowerCase() === 'red');
          if (isBanned) continue;
          const cap = Number(p[`vendor${m[1]}`] || 0);
          const cpi = Number(p[k] || 0);
          if (cap > 0 && cpi > 0 && cpi < minCpi) {
            minCpi = cpi;
            bestVendor = vMeta?.name || `Vendor ${m[1]}`;
          }
        }
      }
    });

    if (bestVendor && isFinite(minCpi)) {
      text = `### 📁 What Was Checked\n\n* Audited external vendor matrices across active markets to locate the lowest unit CPI procurement costs.\n\n\n### 💡 Solution & Allocation Analytics\n\n* **Cheapest Source**: **${bestVendor}** has unit rates starting at **$${minCpi.toFixed(2)}**.\n\n* **Operations Suggestion**: Ensure calculation strategy is set to **"cost"** to automatically prioritize routing completes to this vendor first.`;
    } else {
      text = `### 📁 What Was Checked\n\n* Audited active scenarios for vendor CPIs.\n\n\n### 💡 Solution & Allocation Analytics\n\n* No active vendor CPIs > $0 found yet. Click **Check Feasibility** to load vendor rates from the database.`;
    }
  }
  // 3. CHEAPEST / OPTIMIZE STRATEGY
  else if (query.includes("cheapest") || query.includes("optimize") || query.includes("lowest cost") || query.includes("cheapest version") || query.includes("cel mai ieftin") || query.includes("cea mai ieftin")) {
    const hasManualOverrides = originalPitches.some((p: any) => {
      if (p.maxInternalPercent !== undefined && p.maxInternalPercent < 100) return true;
      if (p.internalPctOverride !== undefined) return true;
      if (p.overlapVariable !== undefined) return true;
      if (p.targetedCpi !== undefined && p.targetedCpi > 0) return true;
      for (const key of Object.keys(p)) {
        if (/^vendor\d+PctOverride$/i.test(key) && p[key] !== undefined) return true;
        if (/^vendor\d+Pct$/i.test(key) && p[key] !== undefined && p[key] !== 100) return true;
      }
      return false;
    });

    if (hasManualOverrides) {
      return {
        text: `### ⚠️ Manual Overrides Detected\n\nWe have active manual overrides on your current scenarios (such as custom internal/vendor share percentages, internal caps, overlap overrides, or targeted CPI limits).\n\nHow would you like to proceed?\n\n* **Reset Overrides & Check Cheapest Offer**: Clear all manual overrides and run the lowest-cost standard feasibility check.\n* **Keep Overrides & Check Remaining Feasibility**: Preserve all your manual adjustments and run **Feasibility Optimized** for the remaining feasibility according to verification rules.`,
        updatedPitches: null,
        updateStrategy: undefined,
        requiresOverrideChoice: true
      };
    }

    updateStrategy = "cost";

    for (const [id, pitch] of pitchesMap.entries()) {
      if (pitch.isLocked) continue;
      pitch.maxInternalPercent = 100;
      hasModifications = true;
    }

    text = `### 📁 What Was Checked\n\n* Triggered local procurement cost optimization engine on **${originalPitches.length} active scenarios**.\n\n* Objective: Maximize use of zero-cost internal panel capabilities within fixed available vendor parameters.\n\n\n### 💡 Solution & Allocation Analytics\n\n* **Optimization Actions Applied**:\n  1. Forced **maximum internal panel contribution to 100%** across all unlocked scenarios.\n  2. Adjusted Calculation Strategy type to **"cost"** (Ascending order of Vendor CPI).\n\n* **Resulting Status**: Feasibility is optimized using actual fixed vendor rates while maximizing internal panel coverage. State representation synchronizes across all panels instantly.`;
  }
  // 4. ADD / INSERT NEW LINE (zero fabricated capacities or guessed specs)
  else if (
    isAddIntent ||
    query.includes("add") ||
    query.includes("insert") ||
    query.includes("adauga") ||
    query.includes("adaugă") ||
    query.includes("new line") ||
    query.includes("row")
  ) {
    const parsed = parseNaturalLanguageSpecs(lastMsg, insertedDb);
    const irDecimal = parsed.irRaw ? (parseFloat(parsed.irRaw.replace(/[^0-9.]/g, "")) || 0) / 100 : 0;

    const newId = `row-proc-${Date.now()}-${Math.floor(Math.random() * 10000)}`;
    const optionNum = String(pitchesMap.size + 1);
    const copiedPitchName = originalPitches[0]?.pitchName || "Pitch 1";

    const newRow = {
      id: newId,
      pitchName: copiedPitchName,
      source: "Chat Spec Add",
      option: optionNum,
      market: parsed.country,
      target: parsed.universe,
      loi: parsed.loi,
      irPercent: irDecimal,
      irUniverse: parsed.universe,
      quotas: parsed.quotas || "No quotas",
      waves: 1,
      totalFreshSample: parsed.targetSize,
      totalSampleSize: parsed.targetSize,
      internal: 0,
      vendor1: 0,
      vendor1Cpi: 0,
      vendor2: 0,
      vendor2Cpi: 0,
      vendor3: 0,
      vendor3Cpi: 0,
      vendor4: 0,
      vendor4Cpi: 0,
      vendor1Pct: 100,
      vendor2Pct: 100,
      vendor3Pct: 100,
      vendor4Pct: 100,
      pmFee: 150,
      salesCpi: 7.50,
      comparability: "High"
    };

    pitchesMap.set(newId, newRow);
    hasModifications = true;

    const dbHints = parsed.country
      ? getCountryPreExistingSpecs(parsed.country, insertedDb)
      : null;

    text = `### 📁 What Was Added\n\n* Mounted new scenario line **Option ${optionNum}** with **0 fabricated capacities** (frontend feasibility engine resolves real database capacities & CPIs).\n\n* **Parsed Specifications (No Assumptions)**:\n  - **Country**: ${parsed.country || '*(empty)*'}\n  - **Target Size**: ${parsed.targetSize > 0 ? `**${parsed.targetSize}**` : '*(0 / empty)*'}\n  - **IR Universe**: ${parsed.universe || '*(empty)*'}\n  - **IR%**: ${parsed.irRaw || '*(0% / empty)*'}\n  - **LOI**: ${parsed.loi > 0 ? `**${parsed.loi} min**` : '*(0 / empty)*'}\n  - **Quotas**: ${newRow.quotas}` +
      (parsed.missingFields.length > 0
        ? `\n\n⚠️ **Unspecified fields left empty**: **${parsed.missingFields.join(', ')}**. Complete them in the grid (or click light-grey cells) to pull database feasibility.`
        : '') +
      (dbHints && dbHints.universes.length > 0
        ? `\n* **Available DB Universes for ${parsed.country}**: ${dbHints.universes.join(', ')}`
        : '');
  }
  // 5. DELETE ROW
  else if (query.includes("delete") || query.includes("remove line") || query.includes("remove row")) {
    const matchRow = lastMsg.match(/row-\w+-\d+/i) || lastMsg.match(/row-ai-\w+-\d+/i);
    let deletedId = "";
    if (matchRow && pitchesMap.has(matchRow[0])) {
      deletedId = matchRow[0];
      pitchesMap.delete(deletedId);
      hasModifications = true;
    } else if (originalPitches.length > 0) {
      deletedId = originalPitches[originalPitches.length - 1].id;
      pitchesMap.delete(deletedId);
      hasModifications = true;
    }

    text = `### 📁 What Was Checked\n\n* Request received to remove option row **${deletedId || 'latest row'}**.\n\n\n### 💡 Solution & Allocation Analytics\n\n* **Action Completed**: Removed specification row from active scenario list. The table view and calculations updated instantly.`;
  }
  // 6. DEFICIT / SHORTAGE AUDIT
  else if (query.includes("deficit") || query.includes("unsatisfied") || query.includes("shortage")) {
    const deficitsList: string[] = [];
    originalPitches.forEach((p: any) => {
      let totalPool = Number(p.internal || 0);
      for (const k of Object.keys(p)) {
        if (/^vendor\d+$/i.test(k)) {
          totalPool += Number(p[k] || 0);
        }
      }
      const target = Number(p.totalSampleSize || 0);
      if (target > 0 && totalPool < target) {
        deficitsList.push(`**${p.market || 'Unspecified'}** (Option ${p.option}): target ${target} vs available capacity ${totalPool} (Shortage: **${target - totalPool} completes**)`);
      }
    });

    if (deficitsList.length > 0) {
      text = `### 📁 What Was Checked\n\n* Audited internal feasibility capacity and active vendor pools against Target sizes across **${originalPitches.length} scenarios**.\n\n\n### 💡 Solution & Allocation Analytics\n\n* Found **${deficitsList.length}** options showing completes deficits under current max capacity pools:\n\n${deficitsList.map(d => `* ${d}`).join('\n\n')}`;
    } else {
      text = `### 📁 What Was Checked\n\n* Audited active scenario list against total feasibility pools (Internal + active Vendors).\n\n\n### 💡 Solution & Allocation Analytics\n\n* **Status**: All active target sizes have raw capacity >= target (verify overlap deductions in **Feasibility Cost Optimizer**).`;
    }
  }
  // 6. DATABASE LOOKUP
  else if (query.includes("database") || query.includes("lookup") || query.includes("inserted")) {
    const db = dataState?.insertedDatabase || [];
    if (db.length === 0) {
      text = `### 📁 What Was Checked\n\n* Checked the capability lookup database storage.\n\n\n### 💡 Solution & Allocation Analytics\n\n* **Status**: No external database file currently mounted. You can upload one via the **"Insert Database"** button in the top navigation bar or the Manage Scenario Specifications tab!`;
    } else {
      const marketsList = Array.from(new Set(db.map((r: any) => r.market || r.Country || 'Unknown'))).slice(0, 8);
      text = `### 📁 What Was Checked\n\n* Queried the local lookup capability database.\n\n\n### 💡 Solution & Allocation Analytics\n\n* **Total Records Loaded**: **${db.length}** rows\n* **Sample Markets**: ${marketsList.join(', ')}${marketsList.length < db.length ? '...' : ''}\n\n* You can cross-reference records or run checks against these targets at any time.`;
    }
  }
  // 7. GENERAL ASSISTANCE & STATUS
  else {
    text = `### 📁 What Was Checked\n\n* Analyzed active feasibility workspace containing **${originalPitches.length} target country groups** and your procurement rules metadata.\n\n\n### 💡 Solution & Allocation Analytics\n\n* **Study Details**:\n  - Number of Active Markets: **${originalPitches.length}**\n  - Active Allocation Strategy: **"${(activeStrategy || 'cost').toUpperCase()}"**\n  - Database Records Mounted: **${dataState?.insertedDatabase?.length || 0}**\n  - Engine Mode: **Local Rule-Based (Deterministic / No AI)**\n\n* I can execute commands such as:\n  * **"create the cheapest version"**\n  * **"add a new line for [Country]"**\n  * **"check deficits"**\n  * **"cheapest source"**\n\nHow would you like to adjust feasibility specifications today?`;
  }

  return {
    text,
    updatedPitches: hasModifications ? Array.from(pitchesMap.values()) : null,
    updateStrategy
  };
}
